p21_fnt_packing_list_line.invoice_line_type,p21_fnt_packing_list_line.detail_type,COALESCE(p21_fnt_packing_list_line.lot_bill, 'N'),p21_fnt_packing_list_line.invoice_line_item_id,p21_fnt_packing_list_line.currency_desc,
p21_fnt_packing_list_line.cust_po_no, p21_fnt_packing_list_line.contract_bin_id, p21_fnt_packing_list_line.bin_notes,p21_fnt_packing_list_line.line, p21_fnt_packing_list_line.line_feed,p21_fnt_packing_list_line.line_station,
p21_fnt_packing_list_line.contract_part_no,p21_fnt_packing_list_line.order_type,p21_fnt_packing_list_line.inv_mast_uid,oe_line_service.row_status_flag service_order_status,CASE inv_mast.other_charge_item   WHEN 'Y' THEN  
NULL   ELSE  inv_mast.haz_mat_flag    END haz_mat_flag,CASE inv_mast.other_charge_item   WHEN 'Y' THEN  NULL   ELSE  CASE inv_mast.haz_mat_flag WHEN 'Y' 
THEN hazmat_code.hazmat_code_desc ELSE    NULL  END    END hazmat_code_description,inv_mast_msds.msds_flag,inv_mast_msds.revision_date,(SELECT 
MAX(invoice_hdr.invoice_date)   FROM invoice_hdr INNER JOIN invoice_line ON invoice_line.invoice_no = invoice_hdr.invoice_no   WHERE invoice_hdr.company_no = P21_fnt_packing_list_line.company_id   AND invoice_hdr.customer_id_number = 
P21_fnt_packing_list_line.customer_id   AND invoice_line.order_no <> P21_fnt_packing_list_line.order_no   AND invoice_line.inv_mast_uid = P21_fnt_packing_list_line.inv_mast_uid) AS 'item_last_invoice_date',CASE service_bin.bin_id WHEN NULL THEN ''
