,p21_fnt_packing_list_line.invoice_line_uid  ,0 total_eco_fee  ,p21_fnt_packing_list_line.upc_code  ,p21_fnt_packing_list_line.ean_code  ,p21_fnt_packing_list_line.gtin_code  ,p21_fnt_packing_list_line.returned_cylinder_quantity  /*MAIN FROM CLAUSE*/  
FROM   p21_fnt_packing_list_line('1','0','9999999999','0','ZZZZZZ',0,999999999,' ','ZZZZZZZZZZ',' ','ZZZZZ',0,999999999,'1990-01-01 00:00:00','2021-10-26 23:59:59',2166283,2166283,0,9999)  LEFT JOIN oe_line_service ON (oe_line_service.oe_line_uid = p21_fnt_packing_list_line.oe_line_uid)  LEFT JOIN oe_line ON (oe_line.oe_line_uid = p21_fnt_packing_list_line.oe_line_uid)  LEFT JOIN inv_mast ON (inv_mast.inv_mast_uid = oe_line.inv_mast_uid)  LEFT OUTER JOIN inv_mast_msds ON (inv_mast_msds.inv_mast_uid = oe_line.inv_mast_uid)  LEFT OUTER JOIN hazmat_code ON (hazmat_code.hazmat_code_uid = inv_mast_msds.hazmat_code_uid)  LEFT JOIN service_inv_mast ON (service_inv_mast.service_inv_mast_uid = oe_line_service.service_inv_mast_uid)  LEFT JOIN bin AS service_bin ON (service_bin.bin_uid = oe_line_service.bin_uid)  /*MAIN WHERE CLAUSE*/  /*MAIN GROUP BY CLAUSE*/  /*MAIN HAVING CLAUSE*/  /*MAIN ORDER BY CLAUSE*/  